-- ReWearMap thrift_stores export (from vinted-tracker backup)
-- Restore after schema exists OR this file recreates the table.
SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;

ALTER TABLE IF EXISTS ONLY public.thrift_stores DROP CONSTRAINT IF EXISTS thrift_stores_pkey;
DROP TABLE IF EXISTS public.thrift_stores;

CREATE TABLE public.thrift_stores (
    id uuid NOT NULL,
    name character varying(200) NOT NULL,
    lat double precision NOT NULL,
    lng double precision NOT NULL,
    next_delivery date,
    delivery_frequency character varying(100) NOT NULL,
    hotness smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    delivery_enabled boolean DEFAULT true NOT NULL,
    delivery_verified boolean DEFAULT false NOT NULL,
    opening_hours character varying(200) DEFAULT ''::character varying NOT NULL,
    facebook_url text DEFAULT ''::text NOT NULL,
    instagram_url text DEFAULT ''::text NOT NULL,
    opening_time character varying(5) DEFAULT ''::character varying NOT NULL,
    delivery_time character varying(5) DEFAULT '08:00'::character varying NOT NULL
);


ALTER TABLE ONLY public.thrift_stores
    ADD CONSTRAINT thrift_stores_pkey PRIMARY KEY (id);

ALTER TABLE public.thrift_stores OWNER TO rewear;
